[{"order":1,"type":"heading","text":"Spatial Data and Custom Types (UserType) in Hibernate"},{"order":2,"type":"paragraph","text":"Handling spatial data like geometries, points, and polygons is a common requirement in modern enterprise applications. While Hibernate Spatial provides robust out-of-the-box support for standard types, developers often encounter proprietary database formats or custom domain models that require specialized mapping. This tutorial explores how to map custom spatial data using Hibernate's UserType interface."},{"order":3,"type":"subheading","text":"Understanding the Hibernate UserType Interface"},{"order":4,"type":"paragraph","text":"The UserType interface in Hibernate allows developers to define custom value types that do not map directly to standard JDBC types. By implementing this interface, you can control how your domain objects are serialized to and deserialized from the database, enabling seamless integration of complex spatial structures."},{"order":5,"type":"subheading","text":"Step 1: Creating the Custom Spatial Domain Model"},{"order":6,"type":"paragraph","text":"First, let us define a simple immutable value object representing a custom 2D Point. This class will be used within our entity models."},{"order":7,"type":"code","text":"public class CustomPoint {
    private final double x;
    private final double y;

    public CustomPoint(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double getX() { return x; }
    public double getY() { return y; }
}"},{"order":8,"type":"subheading","text":"Step 2: Implementing the UserType"},{"order":9,"type":"paragraph","text":"Next, implement the org.hibernate.usertype.UserType interface. This requires defining methods for null safety, equality, deep copying, and JDBC ResultSet extraction/PreparedStatement binding."},{"order":10,"type":"code","text":"import org.hibernate.engine.spi.SharedSessionContractImplementor;
import org.hibernate.usertype.UserType;
import java.io.Serializable;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Types;
import java.util.Objects;

public class CustomPointUserType implements UserType<CustomPoint> {

    @Override
    public int getSqlType() {
        return Types.VARCHAR;
    }

    @Override
    public Class<CustomPoint> returnedClass() {
        return CustomPoint.class;
    }

    @Override
    boolean equals(CustomPoint x, CustomPoint y) {
        return Objects.equals(x, y);
    }

    @Override
    int hashCode(CustomPoint x) {
        return Objects.hash(x.getX(), x.getY());
    }

    @Override
    CustomPoint nullSafeGet(ResultSet rs, int position, SharedSessionContractImplementor session, Object owner) throws SQLException {
        String value = rs.getString(position);
        if (value == null) {
            return null;
        }
        String[] parts = value.split(",");
        return new CustomPoint(Double.parseDouble(parts[0]), Double.parseDouble(parts[1]));
    }

    @Override
    void nullSafeSet(PreparedStatement st, CustomPoint value, int index, SharedSessionContractImplementor session) throws SQLException {
        if (value == null) {
            st.setNull(index, Types.VARCHAR);
        } else {
            String val = value.getX() + "," + value.getY();
            st.setString(index, val);
        }
    }

    @Override
    CustomPoint deepCopy(CustomPoint value) {
        if (value == null) return null;
        return new CustomPoint(value.getX(), value.getY());
    }

    @Override
    boolean isMutable() {
        return false;
    }

    @Override
    Serializable disassemble(CustomPoint value) {
        return value;
    }

    @Override
    CustomPoint assemble(Serializable cached, Object owner) {
        return (CustomPoint) cached;
    }
}"},{"order":11,"type":"subheading","text":"Step 3: Applying the Custom Type to an Entity"},{"order":12,"type":"paragraph","text":"To use your newly created UserType, annotate your entity field with the @Type annotation, referencing the implementation class."},{"order":13,"type":"code","text":"import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import org.hibernate.annotations.Type;

@Entity
@Table(name = "locations")
public class LocationEntity {

    @Id
    @GeneratedValue
    private Long id;

    private String name;

    @Type(CustomPointUserType.class)
    private CustomPoint coordinates;

    // Getters and Setters
}"},{"order":14,"type":"subheading","text":"Best Practices"},{"order":15,"type":"bullet_point","text":"Make your domain spatial objects immutable to prevent unexpected side effects inside the Hibernate persistence context."},{"order":16,"type":"bullet_point","text":"Always implement proper equals and hashCode logic inside your custom UserType and domain models."},{"order":17,"type":"bullet_point","text":"Prefer standard Hibernate Spatial types (like JTS Geometry) unless you are interfacing with non-standard database storage schemas."}]
